Resource: aws_lambda_function.generate_report_lambda
File: /lambdas.tf: 113-142
Guideline: https://docs.prismacloud.io/en/enterprise-edition/policy-reference/aws-policies/aws-serverless-policies/bc-aws-serverless-5

		113 | resource "aws_lambda_function" "generate_report_lambda" {
		114 |   function_name = "reyGasExpress-generateReport-${var.environment}"
		115 |   handler       = "generateReport.handler"
		116 |   runtime       = "nodejs18.x"
		117 |   role          = aws_iam_role.lambda_execution_role.arn
		118 | 
		119 |   filename         = "${var.lambda_code_path}/generateReport.zip"
		120 |   source_code_hash = filebase64sha256("${var.lambda_code_path}/generateReport.zip")
		121 | 
		122 |   timeout     = 90
		123 |   memory_size = 256
		124 | 
		125 |   environment {
		126 |     variables = {
		127 |       ANALYSIS_BUCKET_NAME = aws_s3_bucket.reyGasExpress_analysis_bucket.id
		128 |       REPORTS_BUCKET_NAME  = aws_s3_bucket.reyGasExpress_reports_bucket.id
		129 |       EMAIL_TOPIC_ARN      = aws_sns_topic.reyGasExpress_email_topic.arn
		130 |     }
		131 |   }
		132 | 
		133 |   tracing_config {
		134 |     mode = "Active"
		135 |   }
		136 | 
		137 |   tags = {
		138 |     Environment = var.environment
		139 |     Application = "reyGasExpress"
		140 |     ManagedBy   = "Terraform"
		141 |   }
		142 | }

